  e.id,
  nullif(d.tipo, 'No establecido'),
  nullif(d.responsable_nombre, ''),
  nullif(d.comprador_nombre, ''),
  true
from datos d
join public.empresas e on public.normalizar_texto_sql(e.nombre) = public.normalizar_texto_sql(d.empresa_excel)
on conflict (id_backoffice) do nothing;
